```bash
#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BUILD_DIR="${ROOT_DIR}/build"
SRC_DIR="${ROOT_DIR}/src"
LIB_DIR="${BUILD_DIR}/lib"
BIN_DIR="${BUILD_DIR}/bin"
HW_BUILD_DIR="${BUILD_DIR}/hardware"
VERIFICATION_LOGS="${BUILD_DIR}/verification_logs"
ZK_DIR="${BUILD_DIR}/zk"

mkdir -p "${LIB_DIR}" "${BIN_DIR}" "${HW_BUILD_DIR}" "${VERIFICATION_LOGS}" "${ZK_DIR}"

echo "Phase 1: Compiling Core Numerics (Zig TensorCore)"
zig build-lib -O ReleaseFast --name tensorcore -fPIC -dynamic "${SRC_DIR}/core/tensorcore.zig"
if [ -f "libtensorcore.so" ]; then
  mv libtensorcore.so "${LIB_DIR}/libtensorcore.so"
elif [ -f "libtensorcore.dylib" ]; then
  mv libtensorcore.dylib "${LIB_DIR}/libtensorcore.so"
fi
echo "TensorCore compiled to ${LIB_DIR}/libtensorcore.so"

echo "Phase 2: Hardware Synthesis (Clash & SpinalHDL -> Verilog -> Bitstream)"
echo "  2a: Synthesizing Neuromorphic Core with Clash"
clash --verilog "${SRC_DIR}/hardware/NeuromorphicCore.hs" -o "${HW_BUILD_DIR}/neuromorphic.v.dir" -odir "${HW_BUILD_DIR}"
echo "  2b: Synthesizing FPGA Top Level with SpinalHDL"
(cd "${SRC_DIR}/hardware" && sbt "runMain jaide.hardware.FPGATop")
mv "${SRC_DIR}/hardware/FPGATop.v" "${HW_BUILD_DIR}/"
echo "  2c: Running Yosys for synthesis"
yosys -p "synth_ecp5 -json ${HW_BUILD_DIR}/jaide_fpga.json" "${HW_BUILD_DIR}/FPGATop.v" "${HW_BUILD_DIR}/neuromorphic.v.dir/NeuromorphicCore/NeuromorphicCore.v"
echo "  2d: Running nextpnr for place-and-route"
nextpnr-ecp5 --85k --json "${HW_BUILD_DIR}/jaide_fpga.json" --textcfg "${HW_BUILD_DIR}/jaide_fpga.config" --lpf "${SRC_DIR}/hardware/constraints.pcf"
echo "  2e: Generating bitstream packet"
ecppack "${HW_BUILD_DIR}/jaide_fpga.config" "${HW_BUILD_DIR}/jaide_fpga.bit"
echo "Hardware synthesis complete. Bitstream at ${HW_BUILD_DIR}/jaide_fpga.bit"

echo "Phase 3: Building Polyglot Runtimes"
echo "  3a: Compiling Elixir Actors"
(cd "${SRC_DIR}/actors" && mix local.hex --force && mix local.rebar --force && mix deps.get && mix compile)
echo "  3b: Compiling Pony Actors"
ponyc "${SRC_DIR}/actors/worker.pony" -o "${BIN_DIR}/pony_worker"
echo "  3c: Compiling Gleam Modules"
(cd "${SRC_DIR}/actors" && gleam build)
echo "  3d: Compiling Chapel Parallel Kernels"
chpl "${SRC_DIR}/parallel/orchestrator.chpl" -o "${BIN_DIR}/chapel_orchestrator"
echo "  3e: Compiling Futhark Kernels"
futhark zig "${SRC_DIR}/parallel/kernel.fut" -o "${SRC_DIR}/parallel/futhark_kernel.zig"
(cd "${SRC_DIR}/parallel" && zig build-lib -O ReleaseFast -fPIC -dynamic futhark_kernel.zig -lc)
mv "${SRC_DIR}/parallel/libfuthark_kernel.so" "${LIB_DIR}/"
echo "  3f: Compiling Nim Scheduler"
nim c --opt:speed --threads:on --out:"${BIN_DIR}/scheduler" "${SRC_DIR}/scheduler/longrecipe.nim"
echo "  3g: Compiling Crystal Worker"
crystal build "${SRC_DIR}/actors/worker.cr" -o "${BIN_DIR}/crystal_worker"
echo "  3h: Compiling Vale IPC Parser"
vale "${SRC_DIR}/actors/ipc_parser.vale" -o "${BIN_DIR}/vale_ipc_parser"
echo "  3i: Compiling ATS2 Memory Manager"
patscc -O2 -o "${BIN_DIR}/ats_memory" "${SRC_DIR}/memory/ats_allocator.dats"
echo "  3j: Compiling Terra SIMD Kernels"
terra "${SRC_DIR}/kernels/simd_ops.t" -o "${BIN_DIR}/terra_simd"
echo "  3k: Compiling Racket Macro System"
raco exe -o "${BIN_DIR}/racket_macros" "${SRC_DIR}/meta/macro_expander.rkt"
echo "  3l: Compiling Uiua Array Processor"
uiua build "${SRC_DIR}/array/processor.ua" -o "${BIN_DIR}/uiua_array"
echo "  3m: Compiling BQN Array Engine"
bqn -o "${BIN_DIR}/bqn_engine" "${SRC_DIR}/array/engine.bqn"
echo "  3n: Compiling Hylo Value Semantics Layer"
hylo build "${SRC_DIR}/values/semantics.hylo" -o "${BIN_DIR}/hylo_values"
echo "  3o: Compiling Red Reactive Layer"
red -c -o "${BIN_DIR}/red_reactive" "${SRC_DIR}/reactive/stream.red"
echo "  3p: Compiling Odin Performance Core"
odin build "${SRC_DIR}/perf" -out:"${BIN_DIR}/odin_perf"
echo "  3q: Compiling V Systems Interface"
v -prod -o "${BIN_DIR}/v_interface" "${SRC_DIR}/interface/api.v"

echo "Phase 4: Generating Zero-Knowledge Proof Keys"
echo "  4a: Compiling Circom circuit"
circom "${SRC_DIR}/quantum/computation_proof.circom" --r1cs --wasm --sym -o "${ZK_DIR}"
echo "  4b: Generating trusted setup (powers of tau)"
(cd "${ZK_DIR}" && snarkjs powersoftau new bn128 14 pot14_0000.ptau -v)
(cd "${ZK_DIR}" && echo "jaide_v35_entropy" | snarkjs powersoftau contribute pot14_0000.ptau pot14_0001.ptau --name="JAIDE V35 Initial Contribution" -v)
(cd "${ZK_DIR}" && snarkjs powersoftau prepare phase2 pot14_0001.ptau pot14_final.ptau -v)
echo "  4c: Generating proving and verification keys"
(cd "${ZK_DIR}" && snarkjs groth16 setup computation_proof.r1cs pot14_final.ptau computation_proof_0000.zkey)
(cd "${ZK_DIR}" && echo "jaide_v35_final_entropy" | snarkjs zkey contribute computation_proof_0000.zkey computation_proof_0001.zkey --name="JAIDE V35 Final Key Contribution" -v)
(cd "${ZK_DIR}" && snarkjs zkey export verificationkey computation_proof_0001.zkey verification_key.json)
echo "ZK keys generated in ${ZK_DIR}"

echo "Phase 5: Running Formal Verification Suites (logs in ${VERIFICATION_LOGS})"
echo "  5a: Verifying with Lean4"
lean "${SRC_DIR}/verification/lean/Optimizer.lean" > "${VERIFICATION_LOGS}/lean.log" 2>&1
echo "  5b: Verifying with Isabelle/HOL"
isabelle build -d "${SRC_DIR}/verification/isabelle" > "${VERIFICATION_LOGS}/isabelle.log" 2>&1
echo "  5c: Verifying with Agda"
agda "${SRC_DIR}/verification/agda/Tensor.agda" > "${VERIFICATION_LOGS}/agda.log" 2>&1
echo "  5d: Verifying with Viper"
viperserver "${SRC_DIR}/verification/viper/Memory.vpr" > "${VERIFICATION_LOGS}/viper.log" 2>&1 || true
echo "  5e: Verifying with TLA+"
tlc -config "${SRC_DIR}/verification/tla/Inference.cfg" "${SRC_DIR}/verification/tla/Inference.tla" > "${VERIFICATION_LOGS}/tla.log" 2>&1
echo "  5f: Verifying with Spin/Promela"
(cd "$(dirname "${SRC_DIR}/verification/spin/Protocol.pml")" && spin -a Protocol.pml && gcc -o pan pan.c && ./pan -a > "${VERIFICATION_LOGS}/spin.log" 2>&1 && rm -f pan pan.c pan.b pan.p pan.t)
echo "  5g: Verifying with K Framework"
krun "${SRC_DIR}/verification/k/ProofSemantics.k" > "${VERIFICATION_LOGS}/k.log" 2>&1
echo "  5h: Verifying with Vale"
vale "${SRC_DIR}/verification/vale/SecureIPCParser.vale" > "${VERIFICATION_LOGS}/vale.log" 2>&1
echo "  5i: Verifying with Uppaal"
verifyta -s "${SRC_DIR}/verification/uppaal/System.xml" > "${VERIFICATION_LOGS}/uppaal.log" 2>&1
echo "  5j: Initializing Julia Environment"
(cd "${SRC_DIR}" && julia -e 'using Pkg; Pkg.activate("."); Pkg.instantiate()')
echo "  5k: Checking Prolog Knowledge Base"
swipl -g "consult('${SRC_DIR}/prolog/knowledge_base.pl'), halt." >/dev/null 2>&1

echo "Build complete. Artifacts are in ${BUILD_DIR}"
exit 0
