```zig
const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;

pub const Tensor = struct {
    allocator: Allocator,
    shape: []const u32,
    data: []f32,

    pub fn init(allocator: Allocator, shape: []const u32) !Tensor {
        var size: u64 = 1;
        for (shape) |d| {
            size *= d;
        }
        const data = try allocator.alloc(f32, size);
        @memset(data, 0.0);
        return Tensor{
            .allocator = allocator,
            .shape = try allocator.dupe(u32, shape),
            .data = data,
        };
    }

    pub fn deinit(self: *Tensor) void {
        self.allocator.free(self.shape);
        self.allocator.free(self.data);
        self.* = undefined;
    }

    pub fn getIndex(self: *const Tensor, indices: []const u32) !usize {
        if (indices.len != self.shape.len) {
            return error.ShapeMismatch;
        }
        var index: usize = 0;
        var stride: usize = 1;
        var i: usize = self.shape.len;
        while (i > 0) {
            i -= 1;
            if (indices[i] >= self.shape[i]) {
                return error.IndexOutOfBounds;
            }
            index += indices[i] * stride;
            stride *= self.shape[i];
        }
        return index;
    }

    pub fn get(self: *const Tensor, indices: []const u32) !f32 {
        const index = try self.getIndex(indices);
        return self.data[index];
    }

    pub fn set(self: *Tensor, indices: []const u32, value: f32) !void {
        const index = try self.getIndex(indices);
        self.data[index] = value;
    }

    pub fn fill(self: *Tensor, value: f32) void {
        @memset(self.data, value);
    }

    pub fn zeros(self: *Tensor) void {
        self.fill(0.0);
    }

    pub fn ones(self: *Tensor) void {
        self.fill(1.0);
    }

    pub fn randomUniform(self: *Tensor, prng: *std.rand.Random) void {
        for (self.data) |*val| {
            val.* = prng.float(f32) * 2.0 - 1.0;
        }
    }

    pub fn clone(self: *const Tensor) !Tensor {
        var new_tensor = try Tensor.init(self.allocator, self.shape);
        @memcpy(new_tensor.data, self.data);
        return new_tensor;
    }

    pub fn reshape(self: *Tensor, new_shape: []const u32) !void {
        var new_size: u64 = 1;
        for (new_shape) |d| {
            new_size *= d;
        }
        var old_size: u64 = 1;
        for (self.shape) |d| {
            old_size *= d;
        }
        if (new_size != old_size) {
            return error.ShapeMismatch;
        }
        self.allocator.free(self.shape);
        self.shape = try self.allocator.dupe(u32, new_shape);
    }
};

pub fn matmul(allocator: Allocator, a: *const Tensor, b: *const Tensor) !Tensor {
    if (a.shape.len != 2 or b.shape.len != 2 or a.shape[1] != b.shape[0]) {
        return error.MatmulShapeMismatch;
    }
    const M = a.shape[0];
    const K = a.shape[1];
    const N = b.shape[1];

    var c = try Tensor.init(allocator, &.{ M, N });

    var i: u32 = 0;
    while (i < M) : (i += 1) {
        var j: u32 = 0;
        while (j < N) : (j += 1) {
            var sum: f32 = 0.0;
            var k: u32 = 0;
            while (k < K) : (k += 1) {
                sum += a.data[i * K + k] * b.data[k * N + j];
            }
            c.data[i * N + j] = sum;
        }
    }

    return c;
}

pub fn matmulBatched(allocator: Allocator, a: *const Tensor, b: *const Tensor) !Tensor {
    if (a.shape.len != 3 or b.shape.len != 3) {
        return error.InvalidBatchedShape;
    }
    if (a.shape[0] != b.shape[0] or a.shape[2] != b.shape[1]) {
        return error.BatchedShapeMismatch;
    }
    const batch_size = a.shape[0];
    const M = a.shape[1];
    const K = a.shape[2];
    const N = b.shape[2];

    var c = try Tensor.init(allocator, &.{ batch_size, M, N });

    var b_idx: u32 = 0;
    while (b_idx < batch_size) : (b_idx += 1) {
        const a_offset = b_idx * M * K;
        const b_offset = b_idx * K * N;
        const c_offset = b_idx * M * N;

        var i: u32 = 0;
        while (i < M) : (i += 1) {
            var j: u32 = 0;
            while (j < N) : (j += 1) {
                var sum: f32 = 0.0;
                var k: u32 = 0;
                while (k < K) : (k += 1) {
                    sum += a.data[a_offset + i * K + k] * b.data[b_offset + k * N + j];
                }
                c.data[c_offset + i * N + j] = sum;
            }
        }
    }

    return c;
}

pub fn softmax(t: *Tensor, axis: u32) !void {
    if (axis >= t.shape.len) return error.InvalidAxis;
    if (t.shape.len != 2) return error.NotImplementedForShape;

    const rows = t.shape[0];
    const cols = t.shape[1];

    if (axis == 1) {
        var i: u32 = 0;
        while (i < rows) : (i += 1) {
            const row_start = i * cols;
            const row_slice = t.data[row_start .. row_start + cols];

            var max_val = row_slice[0];
            for (row_slice) |val| {
                if (val > max_val) max_val = val;
            }

            var sum_exp: f32 = 0.0;
            for (row_slice) |*val| {
                const exp_val = @exp(val.* - max_val);
                val.* = exp_val;
                sum_exp += exp_val;
            }

            for (row_slice) |*val| {
                val.* /= sum_exp;
            }
        }
    } else {
        var j: u32 = 0;
        while (j < cols) : (j += 1) {
            var max_val: f32 = t.data[j];
            var i: u32 = 1;
            while (i < rows) : (i += 1) {
                const val = t.data[i * cols + j];
                if (val > max_val) max_val = val;
            }

            var sum_exp: f32 = 0.0;
            i = 0;
            while (i < rows) : (i += 1) {
                const idx = i * cols + j;
                const exp_val = @exp(t.data[idx] - max_val);
                t.data[idx] = exp_val;
                sum_exp += exp_val;
            }

            i = 0;
            while (i < rows) : (i += 1) {
                t.data[i * cols + j] /= sum_exp;
            }
        }
    }
}

pub fn layerNorm(t: *Tensor, epsilon: f32) !void {
    if (t.shape.len != 2) return error.NotImplementedForShape;

    const rows = t.shape[0];
    const cols = t.shape[1];

    var i: u32 = 0;
    while (i < rows) : (i += 1) {
        const row_start = i * cols;
        const row_slice = t.data[row_start .. row_start + cols];

        var mean: f32 = 0.0;
        for (row_slice) |val| {
            mean += val;
        }
        mean /= @as(f32, @floatFromInt(cols));

        var variance: f32 = 0.0;
        for (row_slice) |val| {
            variance += (val - mean) * (val - mean);
        }
        variance /= @as(f32, @floatFromInt(cols));

        const inv_std_dev = 1.0 / @sqrt(variance + epsilon);

        for (row_slice) |*val| {
            val.* = (val.* - mean) * inv_std_dev;
        }
    }
}

pub fn spectralRadius(allocator: Allocator, t: *const Tensor, max_iter: u32) !f32 {
    if (t.shape.len != 2 or t.shape[0] != t.shape[1]) {
        return error.MustBeSquareMatrix;
    }
    const n = t.shape[0];
    var b = try Tensor.init(allocator, &.{ n, 1 });
    defer b.deinit();

    var prng = std.rand.DefaultPrng.init(0);
    const rand = prng.random();
    for (b.data) |*val| {
        val.* = rand.float(f32);
    }

    var b_norm: f32 = 0.0;
    for (b.data) |val| b_norm += val * val;
    b_norm = @sqrt(b_norm);
    for (b.data) |*val| val.* /= b_norm;

    var iter: u32 = 0;
    while (iter < max_iter) : (iter += 1) {
        var ab = try matmul(allocator, t, &b);
        defer ab.deinit();

        var norm: f32 = 0.0;
        for (ab.data) |val| norm += val * val;
        norm = @sqrt(norm);

        var idx: u32 = 0;
        while (idx < n) : (idx += 1) {
            b.data[idx] = ab.data[idx] / norm;
        }
    }

    var ab_final = try matmul(allocator, t, &b);
    defer ab_final.deinit();

    var result: f32 = 0.0;
    var idx: u32 = 0;
    while (idx < n) : (idx += 1) {
        result += b.data[idx] * ab_final.data[idx];
    }
    return result;
}

pub fn transpose(allocator: Allocator, t: *const Tensor) !Tensor {
    if (t.shape.len != 2) return error.InvalidShapeForTranspose;

    const rows = t.shape[0];
    const cols = t.shape[1];
    var result = try Tensor.init(allocator, &.{ cols, rows });

    var i: u32 = 0;
    while (i < rows) : (i += 1) {
        var j: u32 = 0;
        while (j < cols) : (j += 1) {
            result.data[j * rows + i] = t.data[i * cols + j];
        }
    }

    return result;
}

pub fn add(allocator: Allocator, a: *const Tensor, b: *const Tensor) !Tensor {
    if (a.shape.len != b.shape.len) return error.ShapeMismatch;
    for (a.shape, b.shape) |a_dim, b_dim| {
        if (a_dim != b_dim) return error.ShapeMismatch;
    }

    var result = try Tensor.init(allocator, a.shape);
    for (a.data, b.data, result.data) |a_val, b_val, *r_val| {
        r_val.* = a_val + b_val;
    }

    return result;
}

pub fn subtract(allocator: Allocator, a: *const Tensor, b: *const Tensor) !Tensor {
    if (a.shape.len != b.shape.len) return error.ShapeMismatch;
    for (a.shape, b.shape) |a_dim, b_dim| {
        if (a_dim != b_dim) return error.ShapeMismatch;
    }

    var result = try Tensor.init(allocator, a.shape);
    for (a.data, b.data, result.data) |a_val, b_val, *r_val| {
        r_val.* = a_val - b_val;
    }

    return result;
}

pub fn multiply(allocator: Allocator, a: *const Tensor, b: *const Tensor) !Tensor {
    if (a.shape.len != b.shape.len) return error.ShapeMismatch;
    for (a.shape, b.shape) |a_dim, b_dim| {
        if (a_dim != b_dim) return error.ShapeMismatch;
    }

    var result = try Tensor.init(allocator, a.shape);
    for (a.data, b.data, result.data) |a_val, b_val, *r_val| {
        r_val.* = a_val * b_val;
    }

    return result;
}

pub fn scale(allocator: Allocator, t: *const Tensor, scalar: f32) !Tensor {
    var result = try Tensor.init(allocator, t.shape);
    for (t.data, result.data) |val, *r_val| {
        r_val.* = val * scalar;
    }
    return result;
}

pub fn relu(t: *Tensor) void {
    for (t.data) |*val| {
        if (val.* < 0.0) val.* = 0.0;
    }
}

pub fn gelu(t: *Tensor) void {
    const sqrt_2_over_pi = @sqrt(2.0 / math.pi);
    for (t.data) |*val| {
        const x = val.*;
        const cdf = 0.5 * (1.0 + math.tanh(sqrt_2_over_pi * (x + 0.044715 * x * x * x)));
        val.* = x * cdf;
    }
}

pub fn sigmoid(t: *Tensor) void {
    for (t.data) |*val| {
        val.* = 1.0 / (1.0 + @exp(-val.*));
    }
}

pub fn tanh_activation(t: *Tensor) void {
