pub fn sum(t: *const Tensor) f32 {
    var result: f32 = 0.0;
    for (t.data) |val| {
        result += val;
    }
    return result;
}

pub fn mean(t: *const Tensor) f32 {
    return sum(t) / @as(f32, @floatFromInt(t.data.len));
}

pub fn variance(t: *const Tensor, mean_val: f32) f32 {
    var result: f32 = 0.0;
    for (t.data) |val| {
        const diff = val - mean_val;
        result += diff * diff;
    }
    return result / @as(f32, @floatFromInt(t.data.len));
}

pub fn norm(t: *const Tensor) f32 {
    var result: f32 = 0.0;
    for (t.data) |val| {
        result += val * val;
