pub fn convolution1d(allocator: Allocator, input: *const Tensor, kernel: *const Tensor, stride: u32) !Tensor {
    if (input.shape.len != 2 or kernel.shape.len != 2) return error.InvalidConvShape;

    const batch = input.shape[0];
    const in_len = input.shape[1];
    const k_len = kernel.shape[1];

    if (k_len > in_len) return error.KernelTooLarge;

    const out_len = (in_len - k_len) / stride + 1;
    var output = try Tensor.init(allocator, &.{ batch, out_len });

    var b: u32 = 0;
    while (b < batch) : (b += 1) {
        var i: u32 = 0;
        while (i < out_len) : (i += 1) {
            var sum: f32 = 0.0;
            var k: u32 = 0;
            while (k < k_len) : (k += 1) {
                sum += input.data[b * in_len + i * stride + k] * kernel.data[k];
            }
            output.data[b * out_len + i] = sum;
        }
    }

    return output;
}

pub fn pool1dMax(allocator: Allocator, input: *const Tensor, pool_size: u32, stride: u32) !Tensor {
    if (input.shape.len != 2) return error.InvalidPoolShape;

    const batch = input.shape[0];
    const in_len = input.shape[1];
    const out_len = (in_len - pool_size) / stride + 1;

    var output = try Tensor.init(allocator, &.{ batch, out_len });

    var b: u32 = 0;
    while (b < batch) : (b += 1) {
        var i: u32 = 0;
        while (i < out_len) : (i += 1) {
            var max_val: f32 = -math.inf(f32);
            var k: u32 = 0;
            while (k < pool_size) : (k += 1) {
                const val = input.data[b * in_len + i * stride + k];
                if (val > max_val) max_val = val;
            }
            output.data[b * out_len + i] = max_val;
        }
    }

    return output;
}

pub fn batchNorm(t: *Tensor, gamma: []const f32, beta: []const f32, epsilon: f32) !void {
    if (t.shape.len != 2) return error.InvalidBatchNormShape;
    const batch = t.shape[0];
    const features = t.shape[1];

    if (gamma.len != features or beta.len != features) return error.GammaBetaMismatch;

    var mean_vals = try t.allocator.alloc(f32, features);
    defer t.allocator.free(mean_vals);
    var var_vals = try t.allocator.alloc(f32, features);
    defer t.allocator.free(var_vals);

    @memset(mean_vals, 0.0);
    @memset(var_vals, 0.0);

    var b: u32 = 0;
    while (b < batch) : (b += 1) {
        var f: u32 = 0;
        while (f < features) : (f += 1) {
            mean_vals[f] += t.data[b * features + f];
        }
    }

    for (mean_vals) |*m| {
        m.* /= @as(f32, @floatFromInt(batch));
    }

    b = 0;
    while (b < batch) : (b += 1) {
        var f: u32 = 0;
        while (f < features) : (f += 1) {
            const diff = t.data[b * features + f] - mean_vals[f];
            var_vals[f] += diff * diff;
        }
    }

    for (var_vals) |*v| {
        v.* /= @as(f32, @floatFromInt(batch));
    }

    b = 0;
    while (b < batch) : (b += 1) {
        var f: u32 = 0;
        while (f < features) : (f += 1) {
            const idx = b * features + f;
            t.data[idx] = (t.data[idx] - mean_vals[f]) / @sqrt(var_vals[f] + epsilon);
            t.data[idx] = t.data[idx] * gamma[f] + beta[f];
        }
    }
}

pub fn groupNorm(t: *Tensor, num_groups: u32, gamma: []const f32, beta: []const f32, epsilon: f32) !void {
    if (t.shape.len != 2) return error.InvalidGroupNormShape;
    const batch = t.shape[0];
    const features = t.shape[1];

    if (features % num_groups != 0) return error.InvalidNumGroups;
    if (gamma.len != features or beta.len != features) return error.GammaBetaMismatch;

    const group_size = features / num_groups;

    var b: u32 = 0;
    while (b < batch) : (b += 1) {
        var g: u32 = 0;
        while (g < num_groups) : (g += 1) {
            var mean_val: f32 = 0.0;
            var var_val: f32 = 0.0;

            const group_start = g * group_size;
            const group_end = group_start + group_size;

            var idx = group_start;
            while (idx < group_end) : (idx += 1) {
                mean_val += t.data[b * features + idx];
            }
            mean_val /= @as(f32, @floatFromInt(group_size));

            idx = group_start;
            while (idx < group_end) : (idx += 1) {
                const diff = t.data[b * features + idx] - mean_val;
                var_val += diff * diff;
            }
            var_val /= @as(f32, @floatFromInt(group_size));

            const inv_std = 1.0 / @sqrt(var_val + epsilon);

            idx = group_start;
            while (idx < group_end) : (idx += 1) {
                const global_idx = b * features + idx;
                t.data[global_idx] = (t.data[global_idx] - mean_val) * inv_std;
                t.data[global_idx] = t.data[global_idx] * gamma[idx] + beta[idx];
            }
        }
    }
}

pub fn rmsnorm(t: *Tensor, epsilon: f32) !void {
    if (t.shape.len != 2) return error.NotImplementedForShape;
    const rows = t.shape[0];
    const cols = t.shape[1];

    var i: u32 = 0;
    while (i < rows) : (i += 1) {
        const row_start = i * cols;
        const row_slice = t.data[row_start .. row_start + cols];

        var sum_squares: f32 = 0.0;
        for (row_slice) |val| {
            sum_squares += val * val;
        }
        const rms = @sqrt(sum_squares / @as(f32, @floatFromInt(cols)) + epsilon);

        for (row_slice) |*val| {
            val.* /= rms;
        }
    }
}
