pub const AstroLorenzBSplineTokenizer = struct {
    allocator: Allocator,
    vocab: std.StringHashMap(u32),
    reverse_vocab: std.AutoHashMap(u32, []const u8),
    lorenz: LorenzAttractor,
    celestial: CelestialState,
    embedding_dim: u32,
    bspline_degree: u32,
    knots: []f32,
    next_id: u32,

    pub fn init(allocator: Allocator, config: anytype) !AstroLorenzBSplineTokenizer {
        const num_knots = config.embedding_dim + config.bspline_degree + 1;
        var knots_buffer = try allocator.alloc(f32, num_knots);

        var i: usize = 0;
        while (i < config.bspline_degree + 1) : (i += 1) {
            knots_buffer[i] = 0.0;
        }

        const interior_knots = num_knots - 2 * (config.bspline_degree + 1);
        i = 0;
        while (i < interior_knots) : (i += 1) {
            const idx = config.bspline_degree + 1 + i;
            knots_buffer[idx] = @as(f32, @floatFromInt(i + 1)) / @as(f32, @floatFromInt(interior_knots + 1));
        }

        i = num_knots - (config.bspline_degree + 1);
        while (i < num_knots) : (i += 1) {
            knots_buffer[i] = 1.0;
        }

        return AstroLorenzBSplineTokenizer{
            .allocator = allocator,
            .vocab = std.StringHashMap(u32).init(allocator),
            .reverse_vocab = std.AutoHashMap(u32, []const u8).init(allocator),
            .lorenz = LorenzAttractor{
                .sigma = config.lorenz_attractor.sigma,
                .rho = config.lorenz_attractor.rho,
                .beta = config.lorenz_attractor.beta,
            },
            .celestial = CelestialState.init(),
            .embedding_dim = config.embedding_dim,
            .bspline_degree = config.bspline_degree,
            .knots = knots_buffer,
            .next_id = 4,
        };
    }

    pub fn deinit(self: *AstroLorenzBSplineTokenizer) void {
        self.allocator.free(self.knots);
        var it = self.reverse_vocab.valueIterator();
        while (it.next()) |text_ptr| {
            self.allocator.free(text_ptr.*);
        }
        self.vocab.deinit();
        self.reverse_vocab.deinit();
        self.* = undefined;
    }

    pub fn addToken(self: *AstroLorenzBSplineTokenizer, text: []const u8) !u32 {
        if (self.vocab.get(text)) |id| {
            return id;
        }
        const id = self.next_id;
        self.next_id += 1;
        const owned_text = try self.allocator.dupe(u8, text);
        try self.vocab.put(owned_text, id);
        try self.reverse_vocab.put(id, owned_text);
        return id;
    }

    pub fn encode(self: *AstroLorenzBSplineTokenizer, text: []const u8, timestamp: u64) ![]Token {
        self.celestial.update(timestamp);
        self.lorenz.reset(timestamp);

        var tokens = std.ArrayList(Token).init(self.allocator);
        defer tokens.deinit();

        var token_texts = std.ArrayList([]const u8).init(self.allocator);
        defer {
            for (token_texts.items) |t| {
                self.allocator.free(t);
            }
            token_texts.deinit();
        }

        var i: usize = 0;
        while (i < text.len) {
            var max_len: usize = @min(16, text.len - i);
            var found = false;
            while (max_len > 0) : (max_len -= 1) {
                const substr = text[i .. i + max_len];
                if (self.vocab.get(substr)) |_| {
                    try token_texts.append(try self.allocator.dupe(u8, substr));
                    i += max_len;
                    found = true;
                    break;
                }
            }
            if (!found) {
                if (i < text.len) {
                    try token_texts.append(try self.allocator.dupe(u8, text[i .. i + 1]));
                    i += 1;
                }
            }
        }

        for (token_texts.items, 0..) |token_text, idx| {
            const token_id = self.vocab.get(token_text) orelse try self.addToken(token_text);

            var embedding = try self.allocator.alloc(f32, self.embedding_dim);
            @memset(embedding, 0.0);

            var emb_idx: usize = 0;
            while (emb_idx < self.embedding_dim) : (emb_idx += 1) {
                self.lorenz.step();
                const lorenz_val = self.lorenz.x;
                const celestial_influence = self.celestial.positions[emb_idx % 12];

                const normalized_t = (@as(f32, @floatFromInt(emb_idx)) + lorenz_val + celestial_influence) / @as(f32, @floatFromInt(self.embedding_dim));
                const clamped_t = @max(0.0, @min(1.0, normalized_t));

                const spline_idx = @as(u32, @intFromFloat(@as(f32, @floatFromInt(token_id)) * 0.1)) % (self.embedding_dim / 2);
                const basis_val = bsplineBasis(spline_idx, self.bspline_degree, clamped_t, self.knots);
                embedding[emb_idx] = basis_val * (1.0 + celestial_influence * 0.1);
            }

            const harmony = self.celestial.getHarmony();

            try tokens.append(Token{
                .id = token_id,
                .text = try self.allocator.dupe(u8, token_text),
                .embedding = embedding,
                .harmony_score = harmony,
            });
        }

        return try tokens.toOwnedSlice();
    }

    pub fn decode(self: *AstroLorenzBSplineTokenizer, token_ids: []const u32) ![]u8 {
        var result = std.ArrayList(u8).init(self.allocator);
        defer result.deinit();

        for (token_ids) |id| {
            if (self.reverse_vocab.get(id)) |text| {
                try result.appendSlice(text);
            } else {
                try result.append('?');
            }
        }

        return try result.toOwnedSlice();
    }

    pub fn freeTokens(self: *AstroLorenzBSplineTokenizer, tokens: []Token) void {
        for (tokens) |token| {
            self.allocator.free(token.text);
            self.allocator.free(token.embedding);
        }
        self.allocator.free(tokens);
    }
};
