    pub fn init(allocator: Allocator, config: anytype, input_dim: u32) !SynastrySparseAttentionLayer {
        const head_dim = config.head_dim;
        const heads = config.heads;
        const total_dim = heads * head_dim;

        var layer = SynastrySparseAttentionLayer{
            .allocator = allocator,
            .heads = heads,
            .head_dim = head_dim,
            .sparsity_factor = config.sparsity_factor,
            .Wq = try Tensor.init(allocator, &.{ input_dim, total_dim }),
            .Wk = try Tensor.init(allocator, &.{ input_dim, total_dim }),
            .Wv = try Tensor.init(allocator, &.{ input_dim, total_dim }),
            .Wo = try Tensor.init(allocator, &.{ total_dim, input_dim }),
        };

        var prng = std.rand.DefaultPrng.init(0);
        const rand = prng.random();

        layer.Wq.randomUniform(&rand);
        layer.Wk.randomUniform(&rand);
        layer.Wv.randomUniform(&rand);
        layer.Wo.randomUniform(&rand);

        return layer;
    }

    pub fn deinit(self: *SynastrySparseAttentionLayer) void {
        self.Wq.deinit();
        self.Wk.deinit();
        self.Wv.deinit();
        self.Wo.deinit();
    }

    pub fn forward(self: *SynastrySparseAttentionLayer, x: *const Tensor, synastry_bias: *const Tensor) !Tensor {
        const seq_len = x.shape[0];
        const input_dim = x.shape[1];

        var Q = try tensorcore.matmul(self.allocator, x, &self.Wq);
        defer Q.deinit();
        var K = try tensorcore.matmul(self.allocator, x, &self.Wk);
        defer K.deinit();
        var V = try tensorcore.matmul(self.allocator, x, &self.Wv);
        defer V.deinit();

        var K_T = try tensorcore.transpose(self.allocator, &K);
        defer K_T.deinit();

        var scores = try tensorcore.matmul(self.allocator, &Q, &K_T);
        defer scores.deinit();

        const scale = 1.0 / @sqrt(@as(f32, @floatFromInt(self.head_dim)));
        for (scores.data) |*s| {
            s.* *= scale;
        }

        if (synastry_bias.shape[0] == seq_len and synastry_bias.shape[1] == seq_len) {
            for (0..scores.data.len) |i| {
                scores.data[i] += synastry_bias.data[i];
            }
        }

        const threshold = self.findSparsityThreshold(&scores);
        for (scores.data) |*s| {
            if (s.* < threshold) {
                s.* = -1.0e9;
            }
        }

        try tensorcore.softmax(&scores, 1);

        var attn_output = try tensorcore.matmul(self.allocator, &scores, &V);
        defer attn_output.deinit();

        var final_output = try tensorcore.matmul(self.allocator, &attn_output, &self.Wo);
        return final_output;
    }

    fn findSparsityThreshold(self: *const SynastrySparseAttentionLayer, scores: *const Tensor) f32 {
        var sorted_scores = self.allocator.alloc(f32, scores.data.len) catch return 0.0;
        defer self.allocator.free(sorted_scores);

        @memcpy(sorted_scores, scores.data);
        std.mem.sort(f32, sorted_scores, {}, comptime std.sort.desc(f32));

        const k = @as(usize, @intFromFloat(@as(f32, @floatFromInt(scores.data.len)) * self.sparsity_factor));
        if (k >= sorted_scores.len) return sorted_scores[sorted_scores.len - 1];
        return sorted_scores[k];
    }
};

