const std = @import("std");
const tensorcore = @import("tensorcore.zig");
const Tensor = tensorcore.Tensor;
const Allocator = std.mem.Allocator;

const CelestialState = struct {
    positions: [12]f32,
    velocities: [12]f32,
    harmony: f32,
};

pub const CelestialZOO = struct {
    allocator: Allocator,
    learning_rate: f32,
    perturbation_scale: f32,
    spectral_radius_target: f32,
    gradient_clip_norm: f32,
    beta1: f32,
    beta2: f32,
    epsilon: f32,
    weight_decay: f32,
    step_count: u64,
    celestial_state: CelestialState,

    pub fn init(allocator: Allocator, config: anytype) !CelestialZOO {
        return CelestialZOO{
            .allocator = allocator,
            .learning_rate = config.learning_rate,
            .perturbation_scale = config.perturbation_scale,
            .spectral_radius_target = config.spectral_radius_target,
            .gradient_clip_norm = config.gradient_clip_norm,
            .beta1 = config.betas[0],
            .beta2 = config.betas[1],
            .epsilon = config.eps,
            .weight_decay = config.weight_decay,
            .step_count = 0,
            .celestial_state = CelestialState{
                .positions = [_]f32{0.0} ** 12,
                .velocities = [_]f32{0.0} ** 12,
                .harmony = 0.0,
            },
        };
    }

    pub fn deinit(self: *CelestialZOO) void {
        _ = self;
    }

    pub fn updateCelestialState(self: *CelestialZOO, timestamp: u64) void {
        const base_freq: f64 = 2.0 * std.math.pi / 31557600.0;
        const t = @as(f64, @floatFromInt(timestamp));

        self.celestial_state.positions[0] = @as(f32, @floatCast(@sin(t * base_freq)));
        self.celestial_state.positions[1] = @as(f32, @floatCast(@sin(t * base_freq * 12.36)));
        self.celestial_state.positions[2] = @as(f32, @floatCast(@sin(t * base_freq * 4.15)));
        self.celestial_state.positions[3] = @as(f32, @floatCast(@sin(t * base_freq * 1.62)));
        self.celestial_state.positions[4] = @as(f32, @floatCast(@sin(t * base_freq * 0.88)));
        self.celestial_state.positions[5] = @as(f32, @floatCast(@sin(t * base_freq * 0.13)));
        self.celestial_state.positions[6] = @as(f32, @floatCast(@sin(t * base_freq * 0.05)));
        self.celestial_state.positions[7] = @as(f32, @floatCast(@sin(t * base_freq * 0.015)));
        self.celestial_state.positions[8] = @as(f32, @floatCast(@sin(t * base_freq * 0.009)));
        self.celestial_state.positions[9] = @as(f32, @floatCast(@sin(t * base_freq * 0.006)));
        self.celestial_state.positions[10] = @as(f32, @floatCast(@sin(t * base_freq * 0.02)));
        self.celestial_state.positions[11] = @as(f32, @floatCast(@sin(t * base_freq * 0.08)));

        var harmony: f32 = 0.0;
        var i: usize = 0;
        while (i < 12) : (i += 1) {
            var j: usize = i + 1;
            while (j < 12) : (j += 1) {
                const diff = self.celestial_state.positions[i] - self.celestial_state.positions[j];
                const angle = @abs(diff * 180.0);
                const orb = @mod(angle, 360.0);
                if (@abs(orb) < 8.0) harmony += 1.0;
            }
        }
        self.celestial_state.harmony = harmony;
    }

    pub fn step(self: *CelestialZOO, params: []*Tensor, gradients: []*const Tensor) !void {
        if (params.len != gradients.len) return error.ParamGradientMismatch;

        self.step_count += 1;
        self.updateCelestialState(self.step_count);

        const bias_correction1 = 1.0 - std.math.pow(f32, self.beta1, @as(f32, @floatFromInt(self.step_count)));
        const bias_correction2 = 1.0 - std.math.pow(f32, self.beta2, @as(f32, @floatFromInt(self.step_count)));

        const celestial_lr_modifier = 1.0 + self.celestial_state.harmony * 0.01;
        const effective_lr = self.learning_rate * celestial_lr_modifier;

        for (params, gradients) |param, grad| {
            if (param.data.len != grad.data.len) return error.ShapeMismatch;

            for (param.data, grad.data, 0..) |*p, g, idx| {
                var grad_val = g;

                grad_val = @max(-self.gradient_clip_norm, @min(self.gradient_clip_norm, grad_val));

                const perturbation = self.perturbation_scale * self.celestial_state.positions[idx % 12];
                grad_val += perturbation;

                const weight_decay_term = self.weight_decay * p.*;
                grad_val += weight_decay_term;

                const m_t = self.beta1 * 0.0 + (1.0 - self.beta1) * grad_val;
                const v_t = self.beta2 * 0.0 + (1.0 - self.beta2) * grad_val * grad_val;

                const m_hat = m_t / bias_correction1;
                const v_hat = v_t / bias_correction2;

                const update = effective_lr * m_hat / (@sqrt(v_hat) + self.epsilon);
                p.* -= update;
            }
        }
    }

    pub fn zeroOrderStep(self: *CelestialZOO, params: []*Tensor, loss_fn: *const fn ([]*const Tensor) anyerror!f32) !void {
        self.step_count += 1;
        self.updateCelestialState(self.step_count);

        const celestial_lr_modifier = 1.0 + self.celestial_state.harmony * 0.01;
        const effective_lr = self.learning_rate * celestial_lr_modifier;

        var prng = std.rand.DefaultPrng.init(self.step_count);
        const rand = prng.random();

        const current_loss = try loss_fn(@ptrCast(params));

        for (params) |param| {
            for (param.data, 0..) |*p, idx| {
                const perturbation = (rand.float(f32) * 2.0 - 1.0) * self.perturbation_scale;
                const original_value = p.*;

                p.* += perturbation;
                const loss_plus = try loss_fn(@ptrCast(params));

                p.* = original_value - perturbation;
                const loss_minus = try loss_fn(@ptrCast(params));

                p.* = original_value;

                const finite_diff_grad = (loss_plus - loss_minus) / (2.0 * perturbation);

                const celestial_mod = self.celestial_state.positions[idx % 12] * 0.01;
                const grad = finite_diff_grad + celestial_mod;

                p.* -= effective_lr * grad;
            }
        }
    }

    pub fn adjustSpectralRadius(self: *CelestialZOO, reservoir_matrix: *Tensor) !void {
        const current_radius = try tensorcore.spectralRadius(self.allocator, reservoir_matrix, 20);

        if (@abs(current_radius - self.spectral_radius_target) > 0.01) {
            const scale_factor = self.spectral_radius_target / current_radius;
            for (reservoir_matrix.data) |*val| {
                val.* *= scale_factor;
            }
        }
    }
};
