        const num_weights = config.tgn_heads * 2;
        var weights = try allocator.alloc(Tensor, num_weights);
        for (weights, 0..) |*w, i| {
            w.* = try Tensor.init(allocator, &.{ embedding_dim, embedding_dim });
            var prng = std.rand.DefaultPrng.init(@as(u64, @intCast(i)) + 7919);
            const rand = prng.random();
