    pub fn deinit(self: *FractalMemoryLayer) void {
        for (self.tgn_weights) |*w| {
            w.deinit();
        }
        self.allocator.free(self.tgn_weights);
        self.allocator.free(self.htm_synapses);
        self.allocator.free(self.vsa_vectors);
        for (self.fractal_branches) |branch| {
            self.allocator.free(branch);
        }
        self.allocator.free(self.fractal_branches);

