            }
            if (oldest_key != std.math.maxInt(u64)) {
                if (self.temporal_graph_edges.fetchRemove(oldest_key)) |kv| {
                    self.allocator.free(kv.value);
                }
            }
        }

        const edge_count = @min(16, state.data.len / 8);
        var edges = try self.allocator.alloc(u32, edge_count);

        var i: usize = 0;
        while (i < edge_count) : (i += 1) {
            const idx = @as(u32, @intFromFloat(@abs(state.data[i * 8]) * 1000.0)) % @as(u32, @intCast(state.data.len));
            edges[i] = idx;
        }

        try self.temporal_graph_edges.put(timestep, edges);
    }
};

pub const KolmogorovArnoldLayer = struct {
    allocator: Allocator,
    grid_size: u32,
    spline_order: u32,
    input_dim: u32,
    output_dim: u32,
    control_points: [][]f32,
    knots: []f32,

    pub fn init(allocator: Allocator, config: anytype, input_dim: u32, output_dim: u32) !KolmogorovArnoldLayer {
        const num_functions = input_dim * output_dim;
        var control_points = try allocator.alloc([]f32, num_functions);

        var prng = std.rand.DefaultPrng.init(9876);
        const rand = prng.random();

        for (control_points) |*cp| {
            cp.* = try allocator.alloc(f32, config.grid_size + config.spline_order + 1);
            for (cp.*) |*val| {
                val.* = rand.float(f32) * 2.0 - 1.0;
            }
        }

        const num_knots = config.grid_size + 2 * config.spline_order + 2;
        var knots = try allocator.alloc(f32, num_knots);

        var i: usize = 0;
        while (i < config.spline_order + 1) : (i += 1) {
            knots[i] = 0.0;
        }

        i = 0;
        while (i < config.grid_size) : (i += 1) {
            const idx = config.spline_order + 1 + i;
            knots[idx] = @as(f32, @floatFromInt(i + 1)) / @as(f32, @floatFromInt(config.grid_size + 1));
        }

        i = num_knots - (config.spline_order + 1);
        while (i < num_knots) : (i += 1) {
            knots[i] = 1.0;
        }

        return KolmogorovArnoldLayer{
            .allocator = allocator,
            .grid_size = config.grid_size,
            .spline_order = config.spline_order,
            .input_dim = input_dim,
            .output_dim = output_dim,
            .control_points = control_points,
            .knots = knots,
        };
    }

    pub fn deinit(self: *KolmogorovArnoldLayer) void {
        for (self.control_points) |cp| {
            self.allocator.free(cp);
        }
        self.allocator.free(self.control_points);
        self.allocator.free(self.knots);
    }

    pub fn forward(self: *KolmogorovArnoldLayer, x: *const Tensor) !Tensor {
        if (x.shape.len != 2 or x.shape[1] != self.input_dim) {
            return error.InvalidInputShape;
        }

        const batch_size = x.shape[0];
        var output = try Tensor.init(self.allocator, &.{ batch_size, self.output_dim });

        var batch_idx: u32 = 0;
        while (batch_idx < batch_size) : (batch_idx += 1) {
            var out_idx: u32 = 0;
            while (out_idx < self.output_dim) : (out_idx += 1) {
                var sum: f32 = 0.0;

                var in_idx: u32 = 0;
                while (in_idx < self.input_dim) : (in_idx += 1) {
                    const input_val = x.data[batch_idx * self.input_dim + in_idx];
                    const normalized_input = (input_val + 1.0) / 2.0;
                    const clamped_input = @max(0.0, @min(1.0, normalized_input));

                    const func_idx = out_idx * self.input_dim + in_idx;
                    const spline_val = self.evaluateBSpline(func_idx, clamped_input);
                    sum += spline_val;
                }

                output.data[batch_idx * self.output_dim + out_idx] = sum;
            }
        }

        return output;
    }

    fn evaluateBSpline(self: *const KolmogorovArnoldLayer, func_idx: u32, t: f32) f32 {
        if (func_idx >= self.control_points.len) return 0.0;

        const cp = self.control_points[func_idx];
        const k = self.spline_order;

        var result: f32 = 0.0;
        var i: u32 = 0;
        while (i < cp.len) : (i += 1) {
            const basis = self.bsplineBasis(i, k, t);
            result += cp[i] * basis;
        }

        return result;
    }

    fn bsplineBasis(self: *const KolmogorovArnoldLayer, i: u32, k: u32, t: f32) f32 {
        if (k == 0) {
            if (i + 1 >= self.knots.len) return 0.0;
            if (t >= self.knots[i] and t < self.knots[i + 1]) {
                return 1.0;
            } else {
                return 0.0;
            }
        }

        if (i + k >= self.knots.len or i + k + 1 >= self.knots.len) return 0.0;

        const d1 = self.knots[i + k] - self.knots[i];
        const c1 = if (d1 == 0.0) 0.0 else (t - self.knots[i]) / d1;

        const d2 = self.knots[i + k + 1] - self.knots[i + 1];
        const c2 = if (d2 == 0.0) 0.0 else (self.knots[i + k + 1] - t) / d2;

        return c1 * self.bsplineBasis(i, k - 1, t) + c2 * self.bsplineBasis(i + 1, k - 1, t);
    }
};

pub const SpectralReservoirLayer = struct {
    allocator: Allocator,
    reservoir_size: u32,
    input_dim: u32,
    output_dim: u32,
    spectral_radius: f32,
    sparsity: f32,
    leak_rate: f32,
    W_in: Tensor,
    W_reservoir: Tensor,
    W_out: Tensor,
    state: Tensor,

    pub fn init(allocator: Allocator, config: anytype, input_dim: u32, output_dim: u32) !SpectralReservoirLayer {
        var layer = SpectralReservoirLayer{
            .allocator = allocator,
            .reservoir_size = config.reservoir_size,
            .input_dim = input_dim,
            .output_dim = output_dim,
            .spectral_radius = config.spectral_radius,
            .sparsity = config.sparsity,
            .leak_rate = config.leak_rate,
            .W_in = try Tensor.init(allocator, &.{ input_dim, config.reservoir_size }),
            .W_reservoir = try Tensor.init(allocator, &.{ config.reservoir_size, config.reservoir_size }),
            .W_out = try Tensor.init(allocator, &.{ config.reservoir_size, output_dim }),
            .state = try Tensor.init(allocator, &.{ 1, config.reservoir_size }),
        };

        var prng = std.rand.DefaultPrng.init(54321);
        const rand = prng.random();

        layer.W_in.randomUniform(&rand);

        for (layer.W_reservoir.data) |*val| {
            if (rand.float(f32) > config.sparsity) {
                val.* = rand.float(f32) * 2.0 - 1.0;
            } else {
                val.* = 0.0;
            }
        }

        const current_radius = try tensorcore.spectralRadius(allocator, &layer.W_reservoir, 20);
        if (current_radius > 0.0) {
            const scale = config.spectral_radius / current_radius;
            for (layer.W_reservoir.data) |*val| {
                val.* *= scale;
            }
        }

        layer.W_out.randomUniform(&rand);
        layer.state.zeros();

        return layer;
    }

    pub fn deinit(self: *SpectralReservoirLayer) void {
        self.W_in.deinit();
        self.W_reservoir.deinit();
        self.W_out.deinit();
        self.state.deinit();
    }

    pub fn forward(self: *SpectralReservoirLayer, x: *const Tensor) !Tensor {
        if (x.shape[1] != self.input_dim) return error.InvalidInputDim;

        const batch_size = x.shape[0];
        var outputs = try Tensor.init(self.allocator, &.{ batch_size, self.output_dim });

        var batch_idx: u32 = 0;
        while (batch_idx < batch_size) : (batch_idx += 1) {
            var input_row = try Tensor.init(self.allocator, &.{ 1, self.input_dim });
            defer input_row.deinit();

            @memcpy(input_row.data, x.data[batch_idx * self.input_dim .. (batch_idx + 1) * self.input_dim]);

            var input_contrib = try tensorcore.matmul(self.allocator, &input_row, &self.W_in);
            defer input_contrib.deinit();

            var state_contrib = try tensorcore.matmul(self.allocator, &self.state, &self.W_reservoir);
            defer state_contrib.deinit();

            for (self.state.data, input_contrib.data, state_contrib.data) |*s, i_c, s_c| {
                const new_state = @tanh(i_c + s_c);
                s.* = (1.0 - self.leak_rate) * s.* + self.leak_rate * new_state;
            }

            var output_row = try tensorcore.matmul(self.allocator, &self.state, &self.W_out);
            defer output_row.deinit();

            @memcpy(outputs.data[batch_idx * self.output_dim .. (batch_idx + 1) * self.output_dim], output_row.data);
        }

        return outputs;
    }

    pub fn reset(self: *SpectralReservoirLayer) void {
        self.state.zeros();
    }
};
