const std = @import("std");
const tensorcore = @import("tensorcore.zig");
const tokenizer = @import("tokenizer.zig");
const optimizer = @import("optimizer.zig");
const attention = @import("attention.zig");
const layers = @import("layers.zig");
const Tensor = tensorcore.Tensor;
const Allocator = std.mem.Allocator;
const AstroLorenzBSplineTokenizer = tokenizer.AstroLorenzBSplineTokenizer;
const CelestialZOO = optimizer.CelestialZOO;

pub const JAIDEModel = struct {
    allocator: Allocator,
    config: ModelConfig,
    tokenizer: AstroLorenzBSplineTokenizer,
    optimizer: CelestialZOO,
    embedding: Tensor,
    position_encoding: Tensor,
    fractal_layers: []layers.FractalMemoryLayer,
    kan_layers: []layers.KolmogorovArnoldLayer,
    attention_layers: []attention.SynastrySparseAttentionLayer,
    reservoir_layers: []layers.SpectralReservoirLayer,
    output_projection: Tensor,
    layer_norms: []Tensor,

    pub fn init(allocator: Allocator, config_path: []const u8) !JAIDEModel {
        const config_file = try std.fs.cwd().openFile(config_path, .{});
        defer config_file.close();

        const config_json = try config_file.readToEndAlloc(allocator, 1024 * 1024);
        defer allocator.free(config_json);

        const parsed = try std.json.parseFromSlice(ModelConfig, allocator, config_json, .{});
        defer parsed.deinit();
        const config = parsed.value;

        var tok = try AstroLorenzBSplineTokenizer.init(allocator, config.tokenizer);
        var opt = try CelestialZOO.init(allocator, config.optimizer);

        var embed = try Tensor.init(allocator, &.{ config.tokenizer.vocab_size, config.architecture.embedding_dim });
        var prng = std.rand.DefaultPrng.init(1337);
        const rand = prng.random();
        embed.randomUniform(&rand);

        var pos_enc = try Tensor.init(allocator, &.{ config.architecture.context_window, config.architecture.embedding_dim });
        var pos: u32 = 0;
        while (pos < config.architecture.context_window) : (pos += 1) {
            var dim: u32 = 0;
            while (dim < config.architecture.embedding_dim) : (dim += 1) {
                const angle = @as(f32, @floatFromInt(pos)) / std.math.pow(f32, 10000.0, @as(f32, @floatFromInt(dim)) / @as(f32, @floatFromInt(config.architecture.embedding_dim)));
                if (dim % 2 == 0) {
                    pos_enc.data[pos * config.architecture.embedding_dim + dim] = @sin(angle);
                } else {
                    pos_enc.data[pos * config.architecture.embedding_dim + dim] = @cos(angle);
                }
            }
        }

        const num_layers = config.architecture.num_layers;
        var fractal_layers_list = try allocator.alloc(layers.FractalMemoryLayer, num_layers / 4);
        var kan_layers_list = try allocator.alloc(layers.KolmogorovArnoldLayer, num_layers / 4);
        var attention_layers_list = try allocator.alloc(attention.SynastrySparseAttentionLayer, num_layers / 4);
        var reservoir_layers_list = try allocator.alloc(layers.SpectralReservoirLayer, num_layers / 4);

        var i: usize = 0;
        while (i < num_layers / 4) : (i += 1) {
            fractal_layers_list[i] = try layers.FractalMemoryLayer.init(allocator, config.architecture.layers[0], config.architecture.embedding_dim);
            kan_layers_list[i] = try layers.KolmogorovArnoldLayer.init(allocator, config.architecture.layers[1], config.architecture.embedding_dim, config.architecture.embedding_dim);
            attention_layers_list[i] = try attention.SynastrySparseAttentionLayer.init(allocator, config.architecture.layers[2], config.architecture.embedding_dim);
            reservoir_layers_list[i] = try layers.SpectralReservoirLayer.init(allocator, config.architecture.layers[6], config.architecture.embedding_dim, config.architecture.embedding_dim);
        }

        var output_proj = try Tensor.init(allocator, &.{ config.architecture.embedding_dim, config.tokenizer.vocab_size });
        output_proj.randomUniform(&rand);

        var layer_norms_list = try allocator.alloc(Tensor, num_layers);
        i = 0;
        while (i < num_layers) : (i += 1) {
            layer_norms_list[i] = try Tensor.init(allocator, &.{ config.architecture.embedding_dim });
            layer_norms_list[i].ones();
        }

        return JAIDEModel{
            .allocator = allocator,
            .config = config,
            .tokenizer = tok,
            .optimizer = opt,
            .embedding = embed,
            .position_encoding = pos_enc,
            .fractal_layers = fractal_layers_list,
            .kan_layers = kan_layers_list,
            .attention_layers = attention_layers_list,
            .reservoir_layers = reservoir_layers_list,
            .output_projection = output_proj,
            .layer_norms = layer_norms_list,
        };
    }

    pub fn deinit(self: *JAIDEModel) void {
        self.tokenizer.deinit();
        self.optimizer.deinit();
        self.embedding.deinit();
        self.position_encoding.deinit();

        for (self.fractal_layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.fractal_layers);

        for (self.kan_layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.kan_layers);

        for (self.attention_layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.attention_layers);

        for (self.reservoir_layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.reservoir_layers);

        self.output_projection.deinit();

        for (self.layer_norms) |*ln| {
            ln.deinit();
        }
        self.allocator.free(self.layer_norms);
    }

    pub fn forward(self: *JAIDEModel, input_ids: []const u32, timestep: u64) !Tensor {
        const seq_len = @min(input_ids.len, self.config.architecture.context_window);
        var hidden = try Tensor.init(self.allocator, &.{ seq_len, self.config.architecture.embedding_dim });
        defer hidden.deinit();

        var pos: usize = 0;
        while (pos < seq_len) : (pos += 1) {
            const token_id = input_ids[pos];
            if (token_id >= self.config.tokenizer.vocab_size) return error.TokenIdOutOfRange;

            const emb_start = token_id * self.config.architecture.embedding_dim;
            const emb_end = emb_start + self.config.architecture.embedding_dim;
            const pos_start = pos * self.config.architecture.embedding_dim;
            const pos_end = pos_start + self.config.architecture.embedding_dim;

            for (self.embedding.data[emb_start..emb_end], self.position_encoding.data[pos_start..pos_end], hidden.data[pos_start..pos_end]) |emb, pos_enc, *h| {
                h.* = emb + pos_enc;
            }
        }

        var current = try hidden.clone();

        var i: usize = 0;
        while (i < self.fractal_layers.len) : (i += 1) {
            var fractal_out = try self.fractal_layers[i].forward(&current, timestep + i);
            current.deinit();
            current = fractal_out;

            var kan_out = try self.kan_layers[i].forward(&current);
            var residual = try tensorcore.add(self.allocator, &current, &kan_out);
            current.deinit();
            kan_out.deinit();
            current = residual;

            var synastry_bias = try Tensor.init(self.allocator, &.{ seq_len, seq_len });
            synastry_bias.zeros();

            var attn_out = try self.attention_layers[i].forward(&current, &synastry_bias);
            synastry_bias.deinit();

            residual = try tensorcore.add(self.allocator, &current, &attn_out);
            current.deinit();
            attn_out.deinit();
            current = residual;

            try tensorcore.layerNorm(&current, 1e-5);

            var reservoir_out = try self.reservoir_layers[i].forward(&current);
            residual = try tensorcore.add(self.allocator, &current, &reservoir_out);
            current.deinit();
            reservoir_out.deinit();
            current = residual;
        }

        var logits = try tensorcore.matmul(self.allocator, &current, &self.output_projection);
        current.deinit();

        return logits;
    }

    pub fn generate(self: *JAIDEModel, prompt: []const u8, max_length: u32, temperature: f32) ![]u8 {
        const timestamp = @as(u64, @intCast(std.time.timestamp()));
        const tokens = try self.tokenizer.encode(prompt, timestamp);
        defer self.tokenizer.freeTokens(tokens);

        var token_ids = try self.allocator.alloc(u32, max_length);
        defer self.allocator.free(token_ids);

        for (tokens, 0..) |token, i| {
            token_ids[i] = token.id;
        }

        var current_len = tokens.len;
        var prng = std.rand.DefaultPrng.init(@as(u64, @intCast(std.time.milliTimestamp())));
        const rand = prng.random();

        while (current_len < max_length) : (current_len += 1) {
            var logits = try self.forward(token_ids[0..current_len], timestamp + current_len);
            defer logits.deinit();

            const last_token_logits_start = (current_len - 1) * self.config.tokenizer.vocab_size;
            const last_token_logits_end = last_token_logits_start + self.config.tokenizer.vocab_size;

            var probs = try self.allocator.alloc(f32, self.config.tokenizer.vocab_size);
            defer self.allocator.free(probs);

            for (logits.data[last_token_logits_start..last_token_logits_end], probs) |logit, *prob| {
                prob.* = logit / temperature;
            }

            var max_prob: f32 = probs[0];
            for (probs) |p| {
                if (p > max_prob) max_prob = p;
            }

            var sum_exp: f32 = 0.0;
            for (probs) |*p| {
                p.* = @exp(p.* - max_prob);
                sum_exp += p.*;
            }
            for (probs) |*p| {
                p.* /= sum_exp;
            }

            const r = rand.float(f32);
            var cumsum: f32 = 0.0;
            var next_token: u32 = 0;
            for (probs, 0..) |p, idx| {
                cumsum += p;
                if (cumsum >= r) {
                    next_token = @as(u32, @intCast(idx));
                    break;
                }
            }

            token_ids[current_len] = next_token;

            if (next_token == 1 or next_token == 2) {
                break;
            }
        }

        const result_text = try self.tokenizer.decode(token_ids[0..current_len]);
        return result_text;
    }
};

