{-# LANGUAGE DataKinds #-}
{-# LANGUAGE TypeFamilies #-}
{-# LANGUAGE NoImplicitPrelude #-}
{-# LANGUAGE ScopedTypeVariables #-}

module NeuromorphicCore where

import Clash.Prelude
import qualified Data.List as L

type SpikeTime = Unsigned 16
type Voltage = Signed 16
type Weight = Signed 8
type NeuronIndex = Unsigned 12

data NeuronState = NeuronState
  { voltage :: Voltage
  , threshold :: Voltage
  , refractory :: Unsigned 4
  , lastSpike :: SpikeTime
  }

defaultNeuronState :: NeuronState
defaultNeuronState = NeuronState
  { voltage = 0
  , threshold = 1000
  , refractory = 0
  , lastSpike = 0
  }

data SpikeEvent = SpikeEvent
  { sourceNeuron :: NeuronIndex
  , targetNeuron :: NeuronIndex
  , weight :: Weight
  }

data SynapticPlasticity = SynapticPlasticity
  { learningRate :: Unsigned 8
  , timeConstant :: Unsigned 8
  }

defaultPlasticity :: SynapticPlasticity
defaultPlasticity = SynapticPlasticity
  { learningRate = 10
  , timeConstant = 20
  }

leakyIntegrateFire :: 
  SpikeTime -> 
  Vec 4096 NeuronState -> 
  Vec 256 SpikeEvent -> 
  (Vec 4096 NeuronState, Vec 4096 Bool)
leakyIntegrateFire currentTime neurons spikes = 
  unzip $ imap updateNeuron neurons
  where
    updateNeuron :: KnownNat n => Index 4096 -> NeuronState -> (NeuronState, Bool)
    updateNeuron idx neuron =
      let leaked = leakVoltage neuron
          stimulated = applySpikes idx leaked spikes
          (newState, spiked) = checkThreshold currentTime stimulated
      in (newState, spiked)

leakVoltage :: NeuronState -> NeuronState
leakVoltage neuron
  | refractory neuron > 0 = neuron { refractory = refractory neuron - 1, voltage = 0 }
  | otherwise = neuron { voltage = (voltage neuron * 95) `div` 100 }

applySpikes :: Index 4096 -> NeuronState -> Vec 256 SpikeEvent -> NeuronState
applySpikes idx neuron spikes =
  foldl applySpike neuron (toList spikes)
  where
    applySpike :: NeuronState -> SpikeEvent -> NeuronState
    applySpike n spike
      | targetNeuron spike == resize (pack idx) =
          n { voltage = voltage n + resize (weight spike) * 10 }
      | otherwise = n

checkThreshold :: SpikeTime -> NeuronState -> (NeuronState, Bool)
checkThreshold currentTime neuron
  | voltage neuron >= threshold neuron =
      (neuron { voltage = 0, refractory = 4, lastSpike = currentTime }, True)
  | otherwise =
      (neuron, False)

stdpUpdate ::
  SynapticPlasticity ->
  SpikeTime ->
  SpikeTime ->
  Weight ->
  Weight
stdpUpdate plasticity tPre tPost w
  | tPost > tPre =
      let dt = resize (tPost - tPre)
          delta = (learningRate plasticity * expDecay dt (timeConstant plasticity)) `div` 256
      in saturatingAdd w (resize delta)
  | tPre > tPost =
      let dt = resize (tPre - tPost)
          delta = (learningRate plasticity * expDecay dt (timeConstant plasticity)) `div` 256
      in saturatingSub w (resize delta)
  | otherwise = w

expDecay :: Unsigned 16 -> Unsigned 8 -> Unsigned 16
expDecay dt tau =
  let tauExtended = resize tau :: Unsigned 16
  in if dt < tauExtended * 4
     then (256 * (tauExtended * 4 - dt)) `div` (tauExtended * 4)
     else 0

saturatingAdd :: Weight -> Weight -> Weight
saturatingAdd a b =
  let result = resize a + resize b :: Signed 16
  in if result > 127 then 127 else resize result

saturatingSub :: Weight -> Weight -> Weight
saturatingSub a b =
  let result = resize a - resize b :: Signed 16
  in if result < -128 then -128 else resize result

neuromorphicCore ::
  HiddenClockResetEnable dom =>
  Signal dom SpikeTime ->
  Signal dom (Vec 256 SpikeEvent) ->
  Signal dom (Vec 4096 Bool)
neuromorphicCore timeSignal spikeSignal =
  spikesOut
  where
    (neuronStates, spikesOut) = unbundle $ 
      moore leakyIntegrateFire 
            (\_ out -> out) 
            (repeat defaultNeuronState) 
            (bundle (timeSignal, spikeSignal))

moore :: (HiddenClockResetEnable dom) =>
         (s -> i -> (s, o)) ->
         (s -> o -> o') ->
         s ->
         Signal dom i ->
         Signal dom o'
moore transition output initialState input =
  let states = register initialState nextState
      (nextState, outputs) = unbundle $ transition <$> states <*> input
  in output <$> states <*> outputs

routingNetwork ::
  Vec 4096 Bool ->
  Vec 256 SpikeEvent
routingNetwork spikes =
  let activeNeurons = L.filter snd $ zip [0..] (toList spikes)
      events = L.take 256 $ L.map createEvent activeNeurons
  in fromList $ events L.++ L.replicate (256 - L.length events) defaultEvent
  where
    createEvent (idx, _) =
      SpikeEvent
        { sourceNeuron = resize idx
        , targetNeuron = (resize idx + 1) `mod` 4096
        , weight = 5
        }
    defaultEvent = SpikeEvent 0 0 0

topEntity ::
  Clock System ->
  Reset System ->
  Enable System ->
  Signal System SpikeTime ->
  Signal System (Vec 256 SpikeEvent) ->
  Signal System (Vec 4096 Bool)
topEntity = exposeClockResetEnable neuromorphicCore
