package jaide.hardware

import spinal.core._
import spinal.lib._
import spinal.lib.bus.amba4.axi._

case class FPGATop() extends Component {
  val io = new Bundle {
    val axiSlave = slave(Axi4(Axi4Config(
      addressWidth = 32,
      dataWidth = 512,
      idWidth = 8,
      useLock = false,
      useRegion = false,
      useCache = false,
      useProt = false,
      useQos = false
    )))

    val neuromorphicSpikeOut = out Bits(4096 bits)
    val quantumStateOut = out Bits(127 bits)
    val status = out Bits(32 bits)
  }

  val neuromorphicCore = new NeuromorphicAccelerator()
  val tensorCore = new TensorAccelerator()
  val quantumInterface = new QuantumInterface()
  val memoryController = new MemoryController()

  val axiHandler = new Axi4Handler(io.axiSlave)

  axiHandler.connectNeuromorphic(neuromorphicCore)
  axiHandler.connectTensor(tensorCore)
  axiHandler.connectQuantum(quantumInterface)

  io.neuromorphicSpikeOut := neuromorphicCore.io.spikeOutput
  io.quantumStateOut := quantumInterface.io.quantumState
  io.status := Cat(
    neuromorphicCore.io.busy,
    tensorCore.io.busy,
    quantumInterface.io.busy,
    memoryController.io.readyFlag
  ).resize(32)

  memoryController.io.axiMaster <> io.axiSlave
}

class NeuromorphicAccelerator extends Component {
  val io = new Bundle {
    val enable = in Bool()
    val spikeInput = in Bits(256 bits)
    val spikeOutput = out Bits(4096 bits)
    val busy = out Bool()
  }

  val neuronStates = Mem(SInt(16 bits), 4096)
  val synapticWeights = Mem(SInt(8 bits), 4096 * 64)

  val processingCounter = Reg(UInt(12 bits)) init(0)
  val busyFlag = Reg(Bool()) init(False)

  io.busy := busyFlag

  val spikeOutput = Reg(Bits(4096 bits)) init(0)
  io.spikeOutput := spikeOutput

  when(io.enable && !busyFlag) {
    busyFlag := True
    processingCounter := 0
  }

  when(busyFlag) {
    when(processingCounter < 4096) {
      val neuronIdx = processingCounter
      val currentVoltage = neuronStates.readSync(neuronIdx)

      val leakedVoltage = (currentVoltage * 95) / 100

      var stimulation = S(0, 16 bits)
      for(i <- 0 until 256) {
        when(io.spikeInput(i)) {
          val weightAddr = (neuronIdx << 6) + U(i, 6 bits)
          val weight = synapticWeights.readSync(weightAddr.resized)
          stimulation = stimulation + (weight * 10).resized
        }
      }

      val newVoltage = leakedVoltage + stimulation

      val threshold = S(1000, 16 bits)
      when(newVoltage >= threshold) {
        spikeOutput(processingCounter.resized) := True
        neuronStates.write(neuronIdx, S(0, 16 bits))
      } otherwise {
        spikeOutput(processingCounter.resized) := False
        neuronStates.write(neuronIdx, newVoltage)
      }

      processingCounter := processingCounter + 1
    } otherwise {
      busyFlag := False
    }
  }
}

class TensorAccelerator extends Component {
  val io = new Bundle {
    val enable = in Bool()
    val matrixAAddr = in UInt(32 bits)
    val matrixBAddr = in UInt(32 bits)
    val resultAddr = in UInt(32 bits)
    val dimensions = in UInt(16 bits)
    val busy = out Bool()
  }

  val busyFlag = Reg(Bool()) init(False)
  io.busy := busyFlag

  val rowIdx = Reg(UInt(16 bits)) init(0)
  val colIdx = Reg(UInt(16 bits)) init(0)
  val accumulator = Reg(SInt(32 bits)) init(0)

  when(io.enable && !busyFlag) {
    busyFlag := True
    rowIdx := 0
    colIdx := 0
    accumulator := 0
  }

  when(busyFlag) {
    when(rowIdx < io.dimensions) {
      when(colIdx < io.dimensions) {
        accumulator := accumulator + S(rowIdx.asSInt * colIdx.asSInt)
        colIdx := colIdx + 1
      } otherwise {
        colIdx := 0
        rowIdx := rowIdx + 1
        accumulator := 0
      }
    } otherwise {
      busyFlag := False
    }
  }
}

class QuantumInterface extends Component {
  val io = new Bundle {
    val enable = in Bool()
    val circuitData = in Bits(1024 bits)
    val quantumState = out Bits(127 bits)
    val busy = out Bool()
  }

  val quantumRegisters = Vec(Reg(Bool()) init(False), 127)
  val busyFlag = Reg(Bool()) init(False)

  io.busy := busyFlag
  io.quantumState := Cat(quantumRegisters)

  when(io.enable && !busyFlag) {
    busyFlag := True
    for(i <- 0 until 127) {
      quantumRegisters(i) := io.circuitData(i)
    }
  }

  val phaseCounter = Reg(UInt(8 bits)) init(0)
  when(busyFlag) {
    when(phaseCounter < 200) {
      for(i <- 0 until 126) {
        val entangled = quantumRegisters(i) ^ quantumRegisters(i + 1)
        quantumRegisters(i) := entangled
      }
      phaseCounter := phaseCounter + 1
    } otherwise {
      busyFlag := False
      phaseCounter := 0
    }
  }
}

class MemoryController extends Component {
  val io = new Bundle {
    val axiMaster = master(Axi4(Axi4Config(
      addressWidth = 32,
      dataWidth = 512,
      idWidth = 8
    )))
    val readyFlag = out Bool()
  }

  val readyReg = Reg(Bool()) init(True)
  io.readyFlag := readyReg

  io.axiMaster.ar.valid := False
  io.axiMaster.ar.payload.addr := 0
  io.axiMaster.ar.payload.id := 0
  io.axiMaster.ar.payload.len := 0
  io.axiMaster.ar.payload.size := 6
  io.axiMaster.ar.payload.burst := 1

  io.axiMaster.r.ready := True

  io.axiMaster.aw.valid := False
  io.axiMaster.aw.payload.addr := 0
  io.axiMaster.aw.payload.id := 0
  io.axiMaster.aw.payload.len := 0
  io.axiMaster.aw.payload.size := 6
  io.axiMaster.aw.payload.burst := 1

  io.axiMaster.w.valid := False
  io.axiMaster.w.payload.data := 0
  io.axiMaster.w.payload.strb := 0
  io.axiMaster.w.payload.last := False

  io.axiMaster.b.ready := True
}

class Axi4Handler(axiSlave: Axi4) extends Area {
  val readState = Reg(UInt(3 bits)) init(0)
  val writeState = Reg(UInt(3 bits)) init(0)

  axiSlave.ar.ready := (readState === 0)
  axiSlave.r.valid := (readState === 2)
  axiSlave.r.payload.data := 0
  axiSlave.r.payload.resp := 0
  axiSlave.r.payload.last := True

  axiSlave.aw.ready := (writeState === 0)
  axiSlave.w.ready := (writeState === 1)
  axiSlave.b.valid := (writeState === 2)
  axiSlave.b.payload.resp := 0

  when(axiSlave.ar.fire) {
    readState := 1
  }

  when(readState === 1) {
    readState := 2
  }

  when(axiSlave.r.fire) {
    readState := 0
  }

  when(axiSlave.aw.fire) {
    writeState := 1
  }

  when(axiSlave.w.fire) {
    writeState := 2
  }

  when(axiSlave.b.fire) {
    writeState := 0
  }

  def connectNeuromorphic(core: NeuromorphicAccelerator): Unit = {
    core.io.enable := axiSlave.aw.fire
    core.io.spikeInput := axiSlave.w.payload.data.resized
  }

  def connectTensor(core: TensorAccelerator): Unit = {
    core.io.enable := axiSlave.aw.fire
    core.io.matrixAAddr := axiSlave.aw.payload.addr
    core.io.matrixBAddr := axiSlave.aw.payload.addr + 4096
    core.io.resultAddr := axiSlave.aw.payload.addr + 8192
    core.io.dimensions := 64
  }

  def connectQuantum(iface: QuantumInterface): Unit = {
    iface.io.enable := axiSlave.aw.fire
    iface.io.circuitData := axiSlave.w.payload.data.resized
  }
}

object FPGATop extends App {
  SpinalVerilog(new FPGATop())
}
