template RangeCheck(bits) {
    signal input in;
    signal output out;

    signal bits_decomposed[bits];

    var accumulated = 0;
    for (var i = 0; i < bits; i++) {
        bits_decomposed[i] * (bits_decomposed[i] - 1) === 0;
        accumulated = accumulated + bits_decomposed[i] * (2 ** i);
